gTA(){return"\ub3c5\uc758 \ud53c: \uc5ec\uc655\uc744 \uc9c1\uc811 \uacf5\uaca9\ud558\uba74 25% \ud655\ub960\ub85c \uc911\ub3c5\ub3fc\uc694 (2\ud134 \ub3d9\uc548 \ud134\ub9c8\ub2e4 \ucd5c\ub300 \uccb4\ub825\uc758 3%)."},
Tr(a){return"\uac11\uc637: \uce58\uba85\ud0c0\ub9cc \ud53c\ud574\ub97c \uc8fc\uace0 \ub098\uba38\uc9c0\ub294 \ubaa8\ub450 \ud295\uaca8 \ub098\uac00\uc694. \uc774 \ubcf4\uc2a4\ub97c \uc0c1\ub300\ub85c\ub294 \uce58\uba85\ud0c0 \ud655\ub960\uc774 "+a+"%p \ub0ae\uc544\uc9c0\uba70, \ud655\uc815 \uce58\uba85\ud0c0\ub294 \ud56d\uc0c1 \uc801\uc911\ud574\uc694."},
